--- a/src/settings.ts
+++ b/src/settings.ts
@@ -1,16 +1,32 @@
 export interface Settings {
   theme: 'light' | 'dark'
   notifications: {
     email: boolean
     sms: boolean
   }
 }

+export const DEFAULTS: Settings = {
+  theme: 'light',
+  notifications: { email: true, sms: false },
+}
+
+export function resolveSettings(clinic: Partial<Settings>): Settings {
+  return { ...DEFAULTS, ...clinic }
+}
+
+export function describe(settings: Settings): string {
+  const channels = [
+    settings.notifications.email && 'почта',
+    settings.notifications.sms && 'смс',
+  ].filter(Boolean)
+
+  return channels.length ? channels.join(', ') : 'уведомления выключены'
+}
